<?php
declare(strict_types=1);
function utc_now():string{return gmdate('Y-m-d\\TH:i:s\\Z');}
function rate_limit_or_throw(PDO $db,string $key,array $c):void{$q=$db->prepare('SELECT * FROM submission_rate_limits WHERE key_hash=?');$q->execute([$key]);$r=$q->fetch();if($r&&strtotime($r['window_started_at'])+(int)$c['rate_limit_window_seconds']>time()){if((int)$r['attempt_count']>=(int)$c['rate_limit_max_attempts'])throw new RuntimeException('Too many attempts. Please try again later.');$db->prepare('UPDATE submission_rate_limits SET attempt_count=attempt_count+1,updated_at=? WHERE id=?')->execute([utc_now(),$r['id']]);return;}$db->prepare('INSERT INTO submission_rate_limits(key_hash,window_started_at,attempt_count,updated_at)VALUES(?,?,1,?) ON CONFLICT(key_hash) DO UPDATE SET window_started_at=excluded.window_started_at,attempt_count=1,updated_at=excluded.updated_at')->execute([$key,utc_now(),utc_now()]);}
function save_interest(PDO $db,array $v,array $f,array $c):void{$ip=hash_hmac('sha256',$_SERVER['REMOTE_ADDR']??'',$c['ip_hash_secret']);$ua=hash_hmac('sha256',$_SERVER['HTTP_USER_AGENT']??'',$c['app_secret']);$activity=public_activity();$db->beginTransaction();try{rate_limit_or_throw($db,$ip,$c);$q=$db->prepare('INSERT INTO interest_submissions(activity_id,submission_uuid,form_id,schema_version,name,email,country,payload_json,form_snapshot_json,consent,ip_hash,user_agent_hash,created_at)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([(int)$activity['id'],bin2hex(random_bytes(16)),'interest-form',(int)(public_content()['schemaVersion']??1),$v['name']??'',$v['email']??'',$v['country']??'',json_encode($v,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),json_encode($f,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),!empty($v['consent'])?1:0,$ip,$ua,utc_now()]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
